workflow=['# Author by Lab | zefry\nname: cPanel Enterprise Control Plane Upgrade\non:\n  pull_request:\n    branches: [main]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  cpanel-control-upgrade:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    services:\n      mysql:\n        image: mysql:8.4\n        env:\n          MYSQL_ROOT_PASSWORD: synthetic-test-only\n          MYSQL_DATABASE: oneqay_control_upgrade_test\n        ports: [\'3306:3306\']\n        options: >-\n          --health-cmd="mysqladmin ping -h 127.0.0.1 -psynthetic-test-only"\n          --health-interval=10s --health-timeout=5s --health-retries=10\n    steps:\n      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n        with:\n          fetch-depth: 0\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n      - uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240\n        with:\n          php-version: \'8.3\'\n          extensions: pdo_sqlite, pdo_mysql, dom, zlib, phar, curl\n          tools: composer:v2\n          coverage: none\n      - name: Qualify exact certified-source operator scope\n        if: github.event_name == \'pull_request\' && github.head_ref == \'cpanel-control-plane-20261018\'\n        run: bash tools/qa-cpanel-control-source-envelope.sh "${{ github.event.pull_request.base.sha }}" "${{ github.event.pull_request.head.sha }}"\n      - name: Qualify bounded owner-login probe correction\n        if: github.event_name == \'pull_request\' && github.head_ref == \'cpanel-control-bridge-fix-20261018\'\n        run: bash tools/qa-cpanel-control-bridge-fix-source-envelope.sh "${{ github.event.pull_request.base.sha }}" "${{ github.event.pull_request.head.sha }}"\n      - name: Qualify exact HTTPS retry operator scope\n        if: github.event_name == \'pull_request\' && github.head_ref == \'cpanel-https-retry-20261018\'\n        run: bash tools/qa-cpanel-https-retry-source-envelope.sh "${{ github.event.pull_request.base.sha }}" "${{ github.event.pull_request.head.sha }}"\n      - name: Install locked dependencies\n        working-directory: apps/web\n        run: composer install --no-interaction --no-progress --prefer-dist\n      - name: Preserve 32 receipts and credentials; add one module migration\n        run: |\n          set -euo pipefail\n          php -l tools/production/cpanel/update-oneqaydev-control-plane.php\n          php -l tools/production/cpanel/install-oneqaydev-control-plane.php\n          php tools/production/tests/oneqaydev-control-operator.php | tee /tmp/control-operator.log\n          grep -Fxq \'CONTROL_OPERATOR_TOTAL=40\' /tmp/control-operator.log\n          php tools/production/tests/oneqaydev-control-upgrade.php | tee /tmp/control-upgrade-sqlite.log\n          grep -Fxq \'CONTROL_UPGRADE_sqlite_PASS assertions=19\' /tmp/control-upgrade-sqlite.log\n          CONTROL_TEST_ENGINE=mysql php tools/production/tests/oneqaydev-control-upgrade.php | tee /tmp/control-upgrade-mysql.log\n          grep -Fxq \'CONTROL_UPGRADE_mysql_PASS assertions=19\' /tmp/control-upgrade-mysql.log\n      - name: Verify website predecessor and candidate through the owner login route\n        run: |\n          set -euo pipefail\n          php tools/production/tests/oneqaydev-control-https.php | tee /tmp/control-https.log\n          grep -Fxq \'CONTROL_HTTPS_OWNER_ROUTE_PASS assertions=7\' /tmp/control-https.log\n      - name: Bind private runtime and validate worker with link and symlink unavailable\n        run: |\n          set -euo pipefail\n          php -d disable_functions=link,symlink tools/production/tests/oneqaydev-fixed-bridge.php no-links | tee /tmp/fixed-bridge.log\n          grep -Fxq \'FIXED_PUBLIC_BRIDGE_NO_LINKS_PASS assertions=20\' /tmp/fixed-bridge.log\n      - name: Archive old releases only after success; restore verified private ZIP on rollback\n        run: |\n          set -euo pipefail\n          php -l tools/production/cpanel/release-retention.php\n          php tools/production/tests/oneqaydev-release-retention.php | tee /tmp/release-retention.log\n          grep -Fxq \'RELEASE_RETENTION_PASS assertions=29\' /tmp/release-retention.log\n      - name: Bound TLS-preserving retries and untouched preflight restart\n        run: |\n          set -euo pipefail\n          php tools/production/tests/oneqaydev-https-transport.php | tee /tmp/https-retry.log\n          grep -Fxq \'HTTPS_TRANSPORT_RETRY_PASS assertions=60\' /tmp/https-retry.log\n', '# Author by Lab | zefry\nname: cPanel Enterprise Control Plane Upgrade\non:\n  pull_request:\n    branches: [main]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  cpanel-control-upgrade:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    services:\n      mysql:\n        image: mysql:8.4\n        env:\n          MYSQL_ROOT_PASSWORD: synthetic-test-only\n          MYSQL_DATABASE: oneqay_control_upgrade_test\n        ports: [\'3306:3306\']\n        options: >-\n          --health-cmd="mysqladmin ping -h 127.0.0.1 -psynthetic-test-only"\n          --health-interval=10s --health-timeout=5s --health-retries=10\n    steps:\n      - uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n        with:\n          fetch-depth: 0\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n      - uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240\n        with:\n          php-version: \'8.3\'\n          extensions: pdo_sqlite, pdo_mysql, dom, zlib, phar\n          tools: composer:v2\n          coverage: none\n      - name: Qualify exact certified-source operator scope\n        if: github.event_name == \'pull_request\' && github.head_ref == \'cpanel-control-plane-20261018\'\n        run: bash tools/qa-cpanel-control-source-envelope.sh "${{ github.event.pull_request.base.sha }}" "${{ github.event.pull_request.head.sha }}"\n      - name: Qualify bounded owner-login probe correction\n        if: github.event_name == \'pull_request\'