uccess; restore verified private ZIP on rollback\n        run: |\n          set -euo pipefail\n          php -l tools/production/cpanel/release-retention.php\n          php tools/production/tests/oneqaydev-release-retention.php | tee /tmp/release-retention.log\n          grep -Fxq \'RELEASE_RETENTION_PASS assertions=29\' /tmp/release-retention.log\n']
